              onPress={retryAI}
              accessibilityRole="button"
              testID="ai-retry-button"
            >
              <Text style={styles.aiRetryButtonText}>Retry AI</Text>
            </TouchableOpacity>
          </View>
        )}

        {/* Form Fields */}
        {photos.length > 0 && (
