                value={title}
                onChangeText={setTitle}
                placeholder="e.g., Nike Sneakers Size 5"
                maxLength={100}
                testID="title-input"
              />
            </View>

            {/* Description */}
            <View style={styles.field}>
              <Text style={styles.label}>Description</Text>
