                      thumbColor="#fff"
                      testID="sp-toggle"
                    />
                  </View>
                  {acceptsSwapPoints && (
                    <View style={styles.spEligibleBadge}>
                      <Text style={styles.spEligibleText}>✓ SP Eligible</Text>
                    </View>
                  )}
                </>
              ) : (
